__NUXT_JSONP__("/inclusion/noticias/limpian_tu_casa_recogen_tus_alimentos_cosen_tu_ropa_y_hacen_tus_traslados_tambien_quieren_derechos_laborales", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u){return {data:[{post:{slug:"limpian_tu_casa_recogen_tus_alimentos_cosen_tu_ropa_y_hacen_tus_traslados_tambien_quieren_derechos_laborales",title:"Limpian tu casa, recogen tus alimentos, cosen tu ropa y hacen tus traslados: también quieren derechos laborales",date:"2026-03-06T19:05:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F68221a86-582b-4d6e-93dd-158daeefe8f1\u002F","img-alt":"Nubia Díaz, María Isidra Llanos, Betty Ávalos y Ana Medina.",autor:"Beatriz Guillén, El País",link:"https:\u002F\u002Felpais.com\u002Fmexico\u002F2026-03-07\u002Flimpian-tu-casa-recogen-tus-alimentos-cosen-tu-ropa-y-hacen-tus-traslados-tambien-quieren-derechos-laborales.html",category:"inclusion",extracto:"Dentro de la plataforma Unidas, Isidra Llanos, Nubia Díaz, Betty Ávalos y Ana Medina relatan la falta de acceso a la salud, a un contrato o a un permiso de maternidad después de cumplir jornadas de 12 horas.",toc:[],body:{type:"root",children:[{type:b,tag:d,props:{},children:[{type:a,value:"Las cuentas de Isidra Llanos no cuadran. Empezó a trabajar como interna en una casa de Xochimilco, en Ciudad de México, a los 14 años. Trabajó 16 horas diarias (la mayoría de semanas sin ni siquiera tener libre los domingos) durante casi tres décadas. Después cumplió jornadas de 12 horas de lunes a sábado limpiando viviendas en la capital. Ahora, con casi 60 años, todavía está empleada un par de días al mes. Sin embargo, Isidra no recibe una pensión, ninguna ayuda del Gobierno mexicano, tampoco tiene derecho a atenderse en el Instituto Mexicano del Seguro Social (IMSS). Para el Estado, las manos pequeñas y los pies rápidos de Isidra Llanos no han trabajado nunca."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Como ella hay otras 2,3 millones de trabajadoras del hogar en México sin acceso a la seguridad social. Pero no solo, hay 318.000 trabajadoras agrícolas también excluidas, hay 800.000 empleadas en maquiladoras con trabajos informales y hay 92.000 conductoras y repartidoras de plataformas digitales desprotegidas. "},{type:b,tag:e,props:{href:"https:\u002F\u002Felpais.com\u002Fmexico\u002F2023-03-08\u002Focho-mujeres-ocho-formas-de-combatir-la-desigualdad-en-el-trabajo.html",rel:[f,g,h],target:i},children:[{type:a,value:"Es 2026 y en México las mujeres trabajadoras"}]},{type:a,value:" deben seguir peleando por tener un contrato, vacaciones, acceso al sistema médico, y un salario igualitario; deben sobrevivir al acoso sexual de compañeros y empleadores, y, además, tienen que cuidar, a sus hijos, a sus padres, a sus parejas. Ante este panorama desgastante, las mujeres han hallado algo: es en la lucha compartida donde está la salida."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Por eso, unos 20 colectivos de cuatro áreas altamente precarizadas (el sector de cuidados, el agrícola, el de indumentaria y plataformas digitales) se han incorporado a la red Unidas, que está apoyada por OXFAM México, Proyecto de Derechos Económicos, Sociales y Culturales (ProDESC), Fundación Avina y Ethos Innovación en Políticas Públicas. Desde el año pasado, en la red se acompaña a las mujeres, se investigan sus condiciones y se preparan las exigencias al Gobierno y al sector privado. Algunas son transversales: urgen más inspecciones de la Secretaría del Trabajo y urge brindar más información a las trabajadoras sobre sus derechos, sobre qué pueden hacer cuando son vulneradas. “También hay que mejorar los sistemas de acceso al IMSS, los protocolos de prevención de la violencia, de atención a quejas y denuncias, también mejorar el sistema de guarderías”, apunta Verónica Rodríguez, socióloga y consultora de Fundación Avina: “En general es la necesidad de cambiar esta visión de que en ciertos trabajos "},{type:b,tag:e,props:{href:"https:\u002F\u002Felpais.com\u002Fmexico\u002F2021-11-21\u002Fla-muerte-en-vida-de-maria-catalina-acosta-una-trabajadora-del-hogar-en-mexico.html",rel:[f,g,h],target:i},children:[{type:a,value:"la explotación está interiorizada en la sociedad"}]},{type:a,value:p}]},{type:a,value:c},{type:b,tag:j,props:{id:""},children:[]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Nubia Díaz, jornalera agrícola, Guasave"}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Cuando estaba embarazada, Nubia Díaz contaba con cuidado los días. Tenía que trabajar, como mínimo, hasta que estuviera de ocho meses para que su hija pudiera nacer en el IMSS. “La gente me decía: ‘Ay, vas a parir aquí en los surcos. Vas a parir aquí en el campo’. Pero me cuidaban, me vigilaban”, relata esta mujer sonriente por videollamada desde Guasave (Sinaloa). La preocupación de Nubia es habitual entre las jornaleras agrícolas. Solo cobran si trabajan; solo tienen seguro social, si trabajan. Por eso todas esconden su embarazo hasta el final, para que en caso de ser despedidas, todavía tengan un mes de cobertura médica."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:q},{type:b,tag:e,props:{href:r,rel:[f,g,h],target:i},children:[{type:a,value:s}]},{type:a,value:t}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:q},{type:b,tag:e,props:{href:r,rel:[f,g,h],target:i},children:[{type:a,value:s}]},{type:a,value:t}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“Casi nadie se pone a pensar cuando tienen frutas o vegetales en su mesa que son cosechados por nosotras. No somos tomadas en cuenta a pesar de que somos la plataforma en donde nace la vida, en la alimentación del país”, apunta Nubia Díaz, que insiste en que el campo es muy generoso, y que tanto a ella, como a compañeras, les ha permitido sacar adelante a su familia: “También producimos muchas profesiones. Tenemos hijos maestros, hijas licenciadas y eso nos da orgullo a las jornaleras del campo que tengamos buenos frutos”."}]},{type:a,value:c},{type:b,tag:j,props:{id:"-1"},children:[{type:b,tag:e,props:{href:"#-1",ariaHidden:k,tabIndex:l},children:[{type:b,tag:m,props:{className:[n,o]},children:[]}]}]},{type:a,value:c},{type:b,tag:j,props:{id:"betty-ávalos-industria-textil-ciudad-juárez"},children:[{type:b,tag:e,props:{href:"#betty-%C3%A1valos-industria-textil-ciudad-ju%C3%A1rez",ariaHidden:k,tabIndex:l},children:[{type:b,tag:m,props:{className:[n,o]},children:[]}]},{type:a,value:"Betty Ávalos, industria textil, Ciudad Juárez"}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Hace no tanto, en las maquilas de Ciudad Juárez, las nuevas trabajadoras tenían una tarea muy específica durante los tres primeros meses. Cada vez que les llegaba la regla, tenían que ir al área de enfermería a mostrar sus toallas sanitarias para demostrar que no estaban embarazadas. “Si no ibas, ellos iban a buscarte a tu área”, relata Betty Ávalos, de la Colectiva de Mujeres Rosa Luxemburgo, que formó parte de la lucha para eliminar esta práctica. Lograron sustituirlo por un cuestionario. “Tenías que dar santo y seña de tu vida sexual y reproductiva, era menos vergonzoso, pero finalmente seguían teniendo control sobre nuestros cuerpos”, señala la defensora."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"La primera vez que Ávalos, ahora de 52 años, entró a una maquila “quería salir corriendo”. “Entré chiquita, a los 15 años. Me asustaba mucho. Volteaba a todos lados y unas paredes enormes, muy encerrado y te gritaban ‘siéntese ahí y haga eso y no se mueva y no puede ir al baño’. Pero tenía que trabajar”, relata ahora la defensora. Ávalos nació en una de las zonas más humildes de Ciudad Juárez, el suroriente, "},{type:b,tag:e,props:{href:"https:\u002F\u002Felpais.com\u002Fmexico\u002F2025-07-27\u002Flos-ninos-olvidados-de-juarez.html",rel:[f,g,h],target:i},children:[{type:a,value:"donde toda la familia debía trabajar para mantenerse con lo mínimo"}]},{type:a,value:". Ella se empleaba en maquilas donde por la noche pudiera estudiar, así acabó la secundaria y la preparatoria."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Fue muy pronto que Ávalos empezó a hacerse la preguntas ahí dentro: ¿por qué el estándar mínimo son ensamblar 5.000 piezas en un turno, si trabajando sin parar solo llego a 3.000? ¿De dónde sacan esos números? “Te ponían estándares que no eran posibles para un cuerpo humano, porque es una forma de control”, relata: “Siempre quedabas en déficit”. En los años 2000, Betty pasó de cobrar 561 pesos a 983 a la semana, es decir, unos 50 dólares por trabajar 48 horas semanales. Ahí empezó a organizarse con otras compañeras, eligió capacitarse y se incluyó en la comisión de seguridad, de ahí hasta los 20 años de lucha laboral que ya lleva ahora."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Las peticiones para la industria maquiladora siguen en la misma línea que cuando se convirtió en el centro vital de Juárez hace décadas: reducción de la jornada, prevención del acoso sexual y control a las empresas extranjeras. Esto último cobra especial importancia con "},{type:b,tag:e,props:{href:"https:\u002F\u002Felpais.com\u002Fmexico\u002F2026-01-20\u002Fla-frontera-aguanta-el-pulso-del-primer-ano-de-trump-ya-paso-el-shock.html",rel:[f,g,h],target:i},children:[{type:a,value:"el regreso de Trump a la Casa Blanca y la incertidumbre económica en la que vive la frontera"}]},{type:a,value:". Algunas empresas se están declarando en quiebra en Estados Unidos y están dejando a los trabajadores desamparados. “Sin liquidación, ni finiquito, después de años trabajados”, relata Ávalos: “"},{type:b,tag:e,props:{href:"https:\u002F\u002Felpais.com\u002Finternacional\u002F2026-02-25\u002Fmexico-esquiva-el-impacto-del-nuevo-arancel-ya-vigente-de-estados-unidos.html",rel:[f,g,h],target:i},children:[{type:a,value:"Hacen falta controles del Estado"}]},{type:a,value:p}]},{type:a,value:c},{type:b,tag:j,props:{id:"isidra-llanos-trabajadora-del-hogar-ciudad-de-méxico"},children:[{type:b,tag:e,props:{href:"#isidra-llanos-trabajadora-del-hogar-ciudad-de-m%C3%A9xico",ariaHidden:k,tabIndex:l},children:[{type:b,tag:m,props:{className:[n,o]},children:[]}]},{type:a,value:"Isidra Llanos, trabajadora del hogar, Ciudad de México"}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Isidra Llanos vivió desde los 14 años en Ciudad de México, pero no pudo salir a conocer la ciudad hasta dos décadas después. Durante años, Llanos vivió recluida como interna de planta en viviendas de la capital, trabajando desde las 6 de la mañana hasta las 10 de la noche, quedándose dormida de pie, cuidando a niños casi de su misma edad, limpiando y cocinando. "},{type:b,tag:e,props:{href:"https:\u002F\u002Felpais.com\u002Fmexico\u002F2023-05-05\u002Ftrabajadoras-del-hogar-en-mexico-cuanto-se-les-debe-de-pagar-en-que-horario-laboran-y-que-derechos-tienen.html",rel:[f,g,h],target:i},children:[{type:a,value:"Por un sueldo"}]},{type:a,value:", recuerda de esos primeros años, de 30 pesos a la semana. Ella que había salido de Libres, su municipio de Puebla, para escapar de la falta de oportunidades, no logró terminar la primaria y la secundaria hasta que tuvo 40 años."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"En México, las trabajadoras del hogar "},{type:b,tag:e,props:{href:"https:\u002F\u002Felpais.com\u002Fmexico\u002F2022-05-16\u002Fmarcelina-bautista-la-trabajadora-del-hogar-que-se-puso-los-guantes-frente-a-los-abusos-hemos-abierto-los-ojos.html",rel:[f,g,h],target:i},children:[{type:a,value:"han conseguido algunos triunfos históricos"}]},{type:a,value:". Como el de 2019, cuando se aprobó una reforma a la Ley Federal del Trabajo para reconocer sus derechos laborales (esto es, que tuvieran un contrato escrito, aguinaldo, vacaciones y seguridad social) o el de 2022 cuando el Senado hizo obligatoria su inscripción en el IMSS. Sin embargo, la ley se ha quedado en el papel. En enero de 2026, apenas había 39.000 mujeres trabajadoras del hogar registradas, según los datos de Unidas. Es decir: solo el 1,5% de todas ellas recibe cobertura médica. Además, en los últimos tres años, la situación incluso ha empeorado y hay 287 trabajadoras menos en el IMSS."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Isidra Llanos, que está ahora en la directiva del Sindicato Nacional de Trabajadores y Trabajadoras del Hogar (Sinactraho, que acaba de cumplir una década), identifica bien la causa: inscribir a los trabajadores en el IMSS es responsabilidad de cada empleador y la inmensa mayoría no lo hace (porque ni siquiera lo conoce, porque no le da importancia o porque no quiere pagar ese extra). Ante ese muro, las trabajadoras suelen reaccionar con silencio por miedo a quedarse sin trabajo. “Nosotras hemos hecho alguna conciliación aquí en el sindicato con algunos empleadores y apoyamos a las compañeras que han sido despedidas”, relata Llanos, que es secretaria general colegiada, de forma voluntaria."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Ella trata de ayudarlas con su propia historia, porque ya lo vivió todo: el trabajo infantil, el acoso sexual, el despotismo: “"},{type:b,tag:e,props:{href:"https:\u002F\u002Felpais.com\u002Finternacional\u002F2017\u002F03\u002F30\u002Fmexico\u002F1490838981_432617.html",rel:[f,g,h],target:i},children:[{type:a,value:"Usted no tiene derechos, ¿dónde dice?"}]},{type:a,value:"“. ”Pues aquí dice: en los derechos del convenio 189 de la Organización Internacional del Trabajo, en la ley Federal del Trabajo, en la ley de Seguridad Social y en la Constitución, que son las más que tenemos, las que nos arropan como trabajadoras del hogar y son la la defensa de los derechos para lograr ese trabajo digno“, contesta ahora firme Llanos, que frente a los abusos se puso a estudiar."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Ana Medina, conductora, Guadalajara"}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"El calor pega en una Guadalajara que apenas supera e"},{type:b,tag:e,props:{href:"https:\u002F\u002Felpais.com\u002Fmexico\u002F2026-02-22\u002Fcae-nemesio-oseguera-el-mencho-el-narco-mas-buscado-en-un-operativo-de-seguridad.html",rel:[f,g,h],target:i},children:[{type:a,value:"l susto de la caída del Mencho"}]},{type:a,value:". Ana Medina, conductora de Ladys Drivers, acaba de volver a trabajar después de un par de días de descanso tras el operativo del Ejército mexicano que acabó con Nemesio Oseguera Cervantes. Ese mismo domingo y lunes, Uber ya no les permitió trabajar, lo que a Medina le parece una medida acertada, porque sabe que compañeros en otras aplicaciones, como Didi, no fueron avisados de que Jalisco entraba en código rojo y toda la población debía resguardarse. Sin embargo, la imposibilidad de trabajar hizo que muchas conductoras no alcanzaran los bonus semanales o mensuales que reciben por horas trabajadas. Un complemento necesario para mantenerse al volante."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Las plataformas de aplicaciones se quedan actualmente un 40% de lo que los usuarios pagan por transporte o repartos. Este porcentaje obliga a que las trabajadoras tengan que hacer las 12 horas máximas que se permiten al día. Eso para llegar al mínimo. En diciembre de 2024 consiguieron una gran victoria al ser reconocida la relación laboral de estas empresas tecnológicas y ellas en la Ley General del Trabajo."},{type:b,tag:e,props:{href:"https:\u002F\u002Felpais.com\u002Fmexico\u002F2025-06-23\u002Freforma-laboral-para-plataformas-digitales-en-mexico-en-que-consiste-y-por-que-protestan-algunos-repartidores.html",rel:[f,g,h],target:i},children:[{type:a,value:" El año pasado se implementó el programa piloto "}]},{type:a,value:"para que empezaran a estar dentro de la seguridad social. Sin embargo, según las 8.000 mujeres incluidas en esta prueba, es muy difícil llegar al umbral para estar protegida."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“El algoritmo es patriarcal”, afirman desde Unidas, porque favorece a quien trabaja en horarios nocturnos, penaliza si rechazas viajes aunque sea por cuestiones de riesgo o inseguridad, y además, si estás 30 días en inactividad (el mínimo tras un parto, por ejemplo) te da de baja de la plataforma. Por eso desde la red piden a la Secretaría del Trabajo una ley con perspectiva de género, acciones afirmativas y tasas diferenciadas."}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Flimpian_tu_casa_recogen_tus_alimentos_cosen_tu_ropa_y_hacen_tus_traslados_tambien_quieren_derechos_laborales",extension:".md",createdAt:u,updatedAt:u}}],fetch:{},mutations:[]}}("text","element","\n","p","a","nofollow","noopener","noreferrer","_blank","h4","true",-1,"span","icon","icon-link","”.","Así, Nubia y otras cientos de miles de trabajadoras recogen maíz, chile, jitomate, papa, cebolla, frijol, garbanzos o arándanos ","https:\u002F\u002Felpais.com\u002Fmexico\u002F2023-06-18\u002Flas-montanas-de-maiz-blanco-sin-compradores-asfixian-al-campo-de-sinaloa.html","en jornadas extenuantes de 12 horas",", embarazadas, sin permitirse parar, solo para que su bebé pueda ser atendido en un hospital si hay complicaciones. La mayoría después no consigue ni siquiera los días de incapacidad que le corresponden. “La misma pobreza en la que estamos nos obliga a ir a trabajar. Una se sacrifica muchas veces, se hace pequeña y no se da cuenta de que tiene derechos que están en la Constitución”, apunta Díaz, de 40 años, que trabaja en el campo, igual que su familia, desde los ocho.","2026-07-19T00:56:17.245Z")));